{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile with the overall body shape, dense fur, head, and paws of a brown bear. Its fur is dark brown over the back, sides, head and limbs with lighter tan on the muzzle and along the ventral midline and belly. A single very large, glossy black, sickle-shaped horn projects from the mid-forehead and arches up and backward then forward over the head. The sides of the neck, the lower flank and belly, and the outer surfaces of all four limbs bear numerous oval, black-rimmed, hollow-looking openings set flush in the fur, and scattered on the chest, shoulders, forelegs, hind legs and just above the paws are smooth, domed, glossy plates that are black to dark reddish-brown. It stands on four thick legs ending in broad clawed paws and has a very short, rounded, fur-covered stub tail at the rear. No wings, gills, tentacles or feathers are visible.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head at the anterior right end, covered in brown fur with a paler tan muzzle, a large black nose at the tip, small brown eyes, and a slightly open mouth showing the lower lip",
      "where": "at the front of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "one long, glossy black, strongly curved horn with a thick segmented base on the forehead, a smooth outer curve and two small pointed projections on the inner concave edge, tapering to a sharp tip",
      "where": "arising from the center of the forehead on top of the head and arching dorsally over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears covered in dense brown fur with slightly darker edges",
      "where": "on the dorsal surface of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, columnar legs covered in long brown fur, with rows of oval black-rimmed openings and glossy domed plates on the outer surfaces",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body ventrally"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with brown fur on the dorsal surface and five long, curved, light tan claws on each, the claws projecting forward from the toes",
      "where": "at the distal ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, rounded, inconspicuous stub covered in the same brown fur as the body",
      "where": "at the posterior left end of the body, just dorsal to the hind leg"
    },
    {
      "part": "plates",
      "looks_like": "multiple smooth, shiny, convex, hard-looking plates, mostly glossy black with some dark reddish-brown, oval to irregularly rounded and larger over joints",
      "where": "on the ventral chest, on the anterior and lateral surfaces of the forelegs, on the lateral hind leg and above the hind paw, and as small caps just above each paw"
    },
    {
      "part": "markings",
      "looks_like": "numerous oval, pit-like openings with raised black rims and dark interiors, arranged in linear rows",
      "where": "a diagonal row of about six on the lateral neck, a longitudinal row of about ten along the lower flank and belly, and smaller clusters of three to six on the lateral hindquarter and on each leg"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
